import{z as s,x as i,o as e,c as l,q as t,j as n,D as a,d as r,s as o,S as A}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"事件驱动框架的解剖","description":"","frontmatter":{"title":"事件驱动框架的解剖","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/bf-event-driven-anatomy.md","filePath":"quant/bf-event-driven-anatomy.md","lastUpdated":1791063341000}'),d={name:"quant/bf-event-driven-anatomy.md"};function p(m,E,h,D,_,c){const B=i("Mermaid");return e(),l("div",null,[E[2]||(E[2]=t('<h1 id="事件驱动框架的解剖" tabindex="-1">事件驱动框架的解剖 <a class="header-anchor" href="#事件驱动框架的解剖" aria-label="Permalink to &quot;事件驱动框架的解剖&quot;">​</a></h1><div class="epigraph"><p>框架与库的分界是控制反转：库等你来调用，框架拥有主循环，在它认为正确的时刻来调用你。</p><footer>—— 据 Johnson and Foote, Designing Reusable Classes, Journal of Object-Oriented Programming, 1988 对框架与控制反转的论述；对照 Pardo, The Evaluation and Optimization of Trading Strategies, 2007 的仿真流程整理</footer></div><p><a href="/quant/de-map">上一课</a>把数据工程收成一台平台：不变量、双时间轴与契约让研究里的每个数字都答得出哪份字节、哪条规则、哪个知识集——引擎设计从此建立在可信数据之上。本课程把事件驱动回测做成能长期维护的软件：部件放在哪、接口是什么、不变量由谁守护。本课给出解剖图——时钟、数据端口、策略端口、撮合模拟器、账本、风控闸门、记录器七个器官——后课的取舍、深化、规模与测试都在这张图上展开。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/quant/event-driven-backtest">事件驱动回测引擎</a>讲清了循环的语义，没有讲工程边界。把策略、撮合器与账本写进一个进程，第一天没事，第三个月出现三种溃烂：策略为了「看一眼现金」直接伸手进账本，回测与实盘的对账从此各说各话；有人在策略回调里读了系统时钟，历史重放的确定性被静默破坏；成交模型与引擎焊死，换一个市场就要动核心。缺的不是更聪明的循环，而是一组器官边界：每类状态只有一个所有者，每条信息只走声明的通道。</p><p><span class="marginnote">术语翻译：控制反转（IoC）就是「把『什么时候调用谁』的决定权从你的代码移交给框架」——你不再写主循环，只交出若干回调函数，框架在事件到达时来调用你。类比：图书馆按开馆时间通知你来取书，而不是你自己想什么时候闯进去就什么时候闯进去。</span></p><h3 id="七个器官与各自的契约" tabindex="-1">七个器官与各自的契约 <a class="header-anchor" href="#七个器官与各自的契约" aria-label="Permalink to &quot;七个器官与各自的契约&quot;">​</a></h3><p><strong>时钟与队列</strong>是全序的唯一来源：引擎按 \\((\\text{timestamp}, \\text{seq})\\) 弹出事件，任何不经队列的状态修改都违规。<strong>数据端口</strong>把历史行情、修订与停复牌事件按到达序交给引擎，策略不得自行开文件。<strong>策略端口</strong>是回调契约——on_bar、on_order、on_timer——策略收到事实、返回意图，不做 IO、不读墙钟。<strong>撮合模拟器</strong>消费请求与行情、产出回报，档位可插拔。<strong>账本</strong>是现金、仓位、均价的唯一真相，只由成交事件更新。<strong>风控闸门</strong>在订单入队前检查在途与持仓限额，拒绝本身是事件。<strong>记录器</strong>把每个事件与每个决策追加落盘，是后课诊断与测试的地基。</p>',8)),(e(),n(A,null,{default:a(()=>[o(B,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20CLK%5B%22%E6%97%B6%E9%92%9F%22%5D%20--%3E%20Q%5B%22%E4%BC%98%E5%85%88%E9%98%9F%E5%88%97%20(timestamp%2C%20seq)%22%5D%0A%20%20Q%20--%3E%20FEED%5B%22%E6%95%B0%E6%8D%AE%E7%AB%AF%E5%8F%A3%22%5D%0A%20%20FEED%20--%3E%20ST%5B%22%E7%AD%96%E7%95%A5%E7%AB%AF%E5%8F%A3%20%E5%9B%9E%E8%B0%83%E8%BF%94%E5%9B%9E%E6%84%8F%E5%9B%BE%22%5D%0A%20%20ST%20--%3E%20RK%5B%22%E9%A3%8E%E6%8E%A7%E9%97%B8%E9%97%A8%22%5D%0A%20%20RK%20--%3E%20Q%0A%20%20Q%20--%3E%20FL%5B%22%E6%92%AE%E5%90%88%E6%A8%A1%E6%8B%9F%E5%99%A8%22%5D%0A%20%20FL%20--%3E%20LB%5B%22%E8%B4%A6%E6%9C%AC%20%E7%8E%B0%E9%87%91%E4%BB%93%E4%BD%8D%E5%9D%87%E4%BB%B7%22%5D%0A%20%20FL%20--%3E%20Q%0A%20%20LB%20--%3E%20RE%5B%22%E8%AE%B0%E5%BD%95%E5%99%A8%20%E4%BA%8B%E4%BB%B6%E6%B5%81%E8%90%BD%E7%9B%98%22%5D%0A%20%20ST%20--%3E%20RE%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>落成代码后按依赖方向审一遍：策略依赖端口类型与事件定义，不依赖引擎；撮合器依赖<a href="/quant/order-state-machine">订单状态机</a>与行情，不依赖策略；账本只认回报。<strong>端口适配器</strong>把「同一策略对象跑在模拟撮合器与真实网关上」变成配置而不是分支：实盘与回测共享状态机语义、只换网关，这正是<a href="/quant/research-sim-prod">研究、模拟、实盘隔离</a>要求的形态，也是对账的前提。</p><p>策略端口的宽窄是关键设计决定。太窄（只给收盘价数组），事件框架退化成向量化的空壳；太宽（把整本账本与撮合器内部递给策略），边界失效。可用的判据：把回调入参抄成文档，凡是「策略在实盘拿不到的」都不能出现在入参里——上帝视角的簿、未来的 bar、别人的订单号，一票否决。</p><p><span class="marginnote">审计一个框架的第一分钟：在策略回调里搜 <code>time.now</code> 与 <code>read_csv</code>。出现任何一个，重放同一份数据就得不到同一条净值——确定性在策略侧已经丢了。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>控制反转买来两样东西。第一是<strong>可重放</strong>：全序事件流加上种子化随机数，同一输入必得同一输出，监管审计、灾备演练与回归测试才有裁判。第二是<strong>可替换</strong>：撮合器、数据源、网关都是接口后面的实现，替换它们不触碰策略；保真度的提升因此变成换档位，而不是重写系统。记录器让「图从哪来」有了答案：诊断与报表读事件流重放，而不是重新计算状态，图与账本才不会变成两套真相。性能优化必须在不破坏全序的前提下做：按品种分区、批量行情编码都合法；「先算完所有信号再一次撮合」不合法，它重新引入了<a href="/quant/event-driven-backtest">事件驱动回测引擎</a>警告的前视。</p><p><span class="marginnote">直觉类比：可重放像「棋谱复盘」——只要记录每一步棋（事件流）和掷骰子的种子，任何人在任何机器上重摆都能得到一模一样的盘面。没有全序事件流的回测像凭记忆复盘：两个人摆出来的局面不一样，争论从此没有裁判。</span></p><p>主循环归谁管，决定了后面的一切：</p>',8)),(e(),n(A,null,{default:a(()=>[o(B,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E9%97%AE%E9%A2%98%3A%20%E4%B8%BB%E5%BE%AA%E7%8E%AF%E5%BD%92%E8%B0%81%E7%AE%A1%3F%22%5D%20--%3E%20LIB%5B%22%E5%BA%93%3A%20%E4%BD%A0%E7%9A%84%E4%BB%A3%E7%A0%81%E6%98%AF%E4%B8%BB%E4%BA%BA%22%5D%0A%20%20Q%20--%3E%20FW%5B%22%E6%A1%86%E6%9E%B6%3A%20%E5%BC%95%E6%93%8E%E6%98%AF%E4%B8%BB%E4%BA%BA%22%5D%0A%20%20LIB%20--%3E%20L1%5B%22%E4%BD%A0%E5%86%B3%E5%AE%9A%E5%85%88%E7%AE%97%E4%BB%80%E4%B9%88%E5%90%8E%E7%AE%97%E4%BB%80%E4%B9%88%22%5D%0A%20%20L1%20--%3E%20L2%5B%22%E9%9A%8F%E6%89%8B%E8%AF%BB%E6%97%B6%E9%92%9F%E3%80%81%E7%BF%BB%E8%B4%A6%E6%9C%AC%3A%20%E6%B2%A1%E4%BA%BA%E6%8B%A6%22%5D%0A%20%20L2%20--%3E%20L3%5B%22%E5%9B%9E%E6%B5%8B%E4%B8%8E%E5%AE%9E%E7%9B%98%E4%B8%A4%E5%A5%97%E8%A1%8C%E4%B8%BA%2C%20%E6%97%A0%E6%B3%95%E9%87%8D%E6%94%BE%22%5D%0A%20%20FW%20--%3E%20F1%5B%22%E5%BC%95%E6%93%8E%E6%8C%89%E5%85%A8%E5%BA%8F%E5%BC%B9%E5%87%BA%E4%BA%8B%E4%BB%B6%22%5D%0A%20%20F1%20--%3E%20F2%5B%22%E5%8F%AA%E5%9C%A8%20on_bar%20%2F%20on_order%20%E6%97%B6%E5%88%BB%E8%B0%83%E7%94%A8%E4%BD%A0%22%5D%0A%20%20F2%20--%3E%20F3%5B%22%E4%BD%A0%E6%8B%BF%E5%88%B0%E4%BA%8B%E5%AE%9E%2C%20%E8%BF%94%E5%9B%9E%E6%84%8F%E5%9B%BE%2C%20%E5%85%B6%E4%BD%99%E4%B8%8D%E5%BD%92%E4%BD%A0%22%5D%0A%20%20F3%20--%3E%20F4%5B%22%E5%90%8C%E4%B8%80%E8%BE%93%E5%85%A5%E5%BF%85%E5%BE%97%E5%90%8C%E4%B8%80%E8%BE%93%E5%87%BA%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>解剖不是劝你一切从框架开始：日频、宽松成交假设的研究，向量化脚本仍是对的工具，框架的价值要等路径依赖出现才兑现（下一课写这条边界）。也不要为调试方便开后门——引擎不知道策略的存在，策略不知道引擎的内部，后门最终都会在生产对账时收费。</p><p><span class="marginnote">常见误区：初学者容易以为「框架=重=慢，向量化永远更快」。日频宽假设下确实如此；但一旦出现路径依赖（止损、部分成交、保证金追缴），向量化要么写不出来、要么偷偷引入前视。框架的慢是常数开销，前视是正确性错误——后者的代价高得多。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>框架即控制反转：引擎拥有时钟与全序事件流，策略是被调用的回调，只返回意图。</li><li>七器官各守一类状态：时钟、数据端口、策略端口、撮合器、账本、风控闸门、记录器。</li><li>同一策略对象经适配器跑模拟与实盘、只换网关，是对账与环境隔离的前提。</li><li>可重放（全序加种子）与可替换（插拔撮合器）是框架买到的两样能力。</li><li>策略回调里不许出现墙钟与文件 IO；诊断必须从记录的事件流重放。</li><li>出处：Johnson and Foote, <em>JOOP</em>, 1988；Pardo, <em>The Evaluation and Optimization of Trading Strategies</em>, 2007；站内<a href="/quant/event-driven-backtest">事件驱动回测引擎</a>、<a href="/quant/order-state-machine">订单状态机</a>各课。</li></ul>',5))])}const g=s(d,[["render",p]]);export{F as __pageData,g as default};
